 1→using System.ComponentModel.DataAnnotations;
 2→
 3→namespace OmgtuPortal;
 4→
 5→public sealed class AppSettings
 6→{
 7→    [Required]
 8→    public required string DatabaseUrl { get; init; }
 9→
10→    [Required]
11→    public required string KeycloakUrl { get; init; }
12→
13→    [Required]
14→    public required string KeycloakRealm { get; init; }
15→
16→    [Required]
17→    public required string KeycloakClientId { get; init; }
18→
19→    [Required]
20→    public required string CorsOrigins { get; init; }
21→
22→    public bool AutoLogin { get; init; }
23→
24→    public string? UniversityProvider { get; init; }
25→    public string? UniversityBaseUrl { get; init; }
26→
27→    public string UploadsPath { get; init; } = "Uploads";
28→    public long MaxFileSizeMb { get; init; } = 50;
29→
30→    public string Authority => $"{KeycloakUrl.TrimEnd('/')}/realms/{KeycloakRealm}";
31→
32→    public static AppSettings FromEnvironment()
33→    {
34→        var settings = new AppSettings
35→        {
36→            DatabaseUrl = GetRequired("DATABASE_URL"),
37→            KeycloakUrl = GetRequired("KEYCLOAK_URL"),
38→            KeycloakRealm = GetRequired("KEYCLOAK_REALM"),
39→            KeycloakClientId = GetRequired("KEYCLOAK_CLIENT_ID"),
40→            CorsOrigins = GetRequired("CORS_ORIGINS"),
41→            AutoLogin = Environment.GetEnvironmentVariable("AUTOLOGIN")?.Equals("true", StringComparison.OrdinalIgnoreCase) ?? false,
42→            UniversityProvider = Environment.GetEnvironmentVariable("UNIVERSITY_PROVIDER"),
43→            UniversityBaseUrl = Environment.GetEnvironmentVariable("UNIVERSITY_BASE_URL"),
44→            UploadsPath = Environment.GetEnvironmentVariable("UPLOADS_PATH") ?? "Uploads",
45→            MaxFileSizeMb = long.TryParse(Environment.GetEnvironmentVariable("MAX_FILE_SIZE_MB"), out var maxSize) ? maxSize : 50,
46→        };
47→
48→        Validate(settings);
49→        return settings;
50→    }
51→
52→    private static string GetRequired(string name)
53→    {
54→        return Environment.GetEnvironmentVariable(name)
55→               ?? throw new InvalidOperationException(
56→                   $"Required environment variable '{name}' is not set. Check your .env file.");
57→    }
58→
59→    private static void Validate(AppSettings settings)
60→    {
61→        var context = new ValidationContext(settings);
62→        var results = new List<ValidationResult>();
63→
64→        if (!Validator.TryValidateObject(settings, context, results, validateAllProperties: true))
65→        {
66→            var errors = string.Join(Environment.NewLine, results.Select(r => r.ErrorMessage));
67→            throw new InvalidOperationException(
68→                $"AppSettings validation failed:{Environment.NewLine}{errors}");
69→        }
70→    }
71→}
